---@class PVPArenaTimeLineNode
---@field GroupFour                     	UnityEngine.RectTransform
---@field GroupThree                    	UnityEngine.RectTransform
local PVPArenaTimeLineNode = Class('PVPArenaTimeLineNode')

------------ import ------------
local KTool          = CS.Engine.Lib.KTool
------------ import ------------

------------ define ------------
local PVPArenaSeasonNodePath = "Game.UI.PVPArena.PVPArenaSeasonNode"

--- 赛季状态 观众状态
local AudienceStatus = {
    Quiz   = 0,  --- 竞猜期
    Notice = 1,  --- 公示期
    Battle = 2,  --- 比赛期
}
local FullStatus2AudienceStatus = {
    [Constants.PVPArenaSeasonFullStatus.Closed] = AudienceStatus.Battle,
    [Constants.PVPArenaSeasonFullStatus.Quiz] = AudienceStatus.Quiz,
    [Constants.PVPArenaSeasonFullStatus.Notice] = AudienceStatus.Notice,
    [Constants.PVPArenaSeasonFullStatus.Group] = AudienceStatus.Battle,
    [Constants.PVPArenaSeasonFullStatus.OffSeason] = AudienceStatus.Battle,
    [Constants.PVPArenaSeasonFullStatus.Final] = AudienceStatus.Battle,
}

--- 赛季状态 选手状态
local PlayersStatus = {
    Prepare   = 0,     --- 备战期
    Group     = 1,     --- 小组赛
    OffSeason = 2,     --- 休赛
    Final     = 3,     --- 最终赛
}
local FullStatus2PlayersStatus = {
    [Constants.PVPArenaSeasonFullStatus.Closed] = PlayersStatus.Final,
    [Constants.PVPArenaSeasonFullStatus.Quiz] = PlayersStatus.Prepare,
    [Constants.PVPArenaSeasonFullStatus.Notice] = PlayersStatus.Prepare,
    [Constants.PVPArenaSeasonFullStatus.Group] = PlayersStatus.Group,
    [Constants.PVPArenaSeasonFullStatus.OffSeason] = PlayersStatus.OffSeason,
    [Constants.PVPArenaSeasonFullStatus.Final] = PlayersStatus.Final,
}

------------ define ------------

function PVPArenaTimeLineNode:__init()
    self.seasonIndex = -1
    ---@type PVPArenaComponent
    local pvpArenaComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PVPArenaComponent)
    self.pvpArenaComponent  = pvpArenaComponent
end

function PVPArenaTimeLineNode:__delete()
    self.seasonIndex = nil
    self.pvpArenaComponent = nil
end

function PVPArenaTimeLineNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end


