--- ui logic begin --
---------------------------------------------------

function PVPArenaTimeLineNode:RefreshUI(isDisableCountdown)
    ---@type PVPArenaComponent
    local pvpArenaComponent = self.pvpArenaComponent
    ---@type PVPArenaEntryDojo
    local pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()

    --------------------------------------
    --- 计算当前的 赛季状态
    local isAudience = checkNumber(pvpArenaEntryDojo.identity) == Constants.PVPArenaIdentity.Audience
    local seasonFlag = pvpArenaComponent:GetSeasonFlag()
    local seasonIndex = self:GetSeasonIndex(seasonFlag, isAudience)

    --------------------------------------
    --- 刷新UI

    --- 第一次刷新
    if self.seasonIndex < 0 then
        KTool.SetActive(self.GroupFour.gameObject, not isAudience)
        KTool.SetActive(self.GroupThree.gameObject, isAudience)
    elseif self.seasonIndex ~= seasonIndex then
        self:RefreshSeasonNode(self.seasonIndex, isAudience, false)
    end
    self:RefreshSeasonNode(seasonIndex, isAudience, true, isDisableCountdown)

    self.seasonIndex = seasonIndex
end

function PVPArenaTimeLineNode:RefreshSeasonNode(idx, isAudience, isShowActiveNode, isDisableCountdown)
    if idx == nil or idx < 0 then
        printError("pvp 未知 idx = %s", tostring(idx))
        return
    end
    local parent = isAudience and self.GroupThree or self.GroupFour
    local seasonNode = parent.transform:GetChild(idx)
    ---@type PVPArenaSeasonNode
    local env =  CfUtils.GetLuaScr(seasonNode.gameObject, PVPArenaSeasonNodePath)
    if isNull(env) then return end
    env:RefreshUI(isShowActiveNode, isDisableCountdown)
end

