---GetSeasonIndex
---@param seasonFlag Constants.PVPArenaSeasonFullStatus
---@param isAudience boolean
function PVPArenaTimeLineNode:GetSeasonIndex(seasonFlag, isAudience)
    return isAudience and FullStatus2AudienceStatus[seasonFlag] or FullStatus2PlayersStatus[seasonFlag]
end

